      agent.on('agent_end', agentEnd);
      runner.on('agent_end', runnerEnd);
      releaseResponse();
      await result.completed;

      expect(agentEnd).toHaveBeenCalledTimes(1);
      expect(agentEnd).toHaveBeenCalledWith(result.state._context, 'done');
      expect(runnerEnd).toHaveBeenCalledTimes(1);
      expect(runnerEnd).toHaveBeenCalledWith(
        result.state._context,
        agent,
        'done',
      );
      expect(result.state._context.usage).toMatchObject({
        requests: 1,
        inputTokens: 2,
        outputTokens: 3,
        totalTokens: 5,
      });
    },
  );

